  "Rg_IdKey" int NOT NULL,
  "Rg_KdIdKey" int NOT NULL,
  "Rg_Nummer" varchar(9) NOT NULL,
  "Rg_Datum" date DEFAULT NULL,
  "Rg_ZahlFristTage" int DEFAULT NULL,
  PRIMARY KEY ("Rg_IdKey")
);

